mapper.select:
SELECT id,record_kind,symbol,business_date,evidence_json,evidence_hash,created_at FROM (
SELECT r.*, ROW_NUMBER() OVER(PARTITION BY record_kind,symbol ORDER BY business_date DESC,id DESC) AS latest_rank
FROM portfolio_revision r WHERE business_date <= #{asOf} AND created_at <= #{cutoff}
) ranked WHERE latest_rank=1 ORDER BY symbol
